use super::*;
fn plan(source:&str)->DocumentScenePlan{
 use crate::schema::{scene_preparation::{DocumentVectorJob,DocumentSceneLimits,DocumentAlgorithmLimits},scene_booleans::DocumentBooleanLimits,scene_trace::DocumentTraceLimits};
 let rows:serde_json::Value=serde_json::from_str(include_str!("../../../../📋️prepare/🧫️fixtures/🎬️vector/🔣️.json")).unwrap();let row=rows.as_array().unwrap().iter().find(|r|r["name"]==source).unwrap();let document:crate::DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let l=&row["limits"];let limits=DocumentSceneLimits{max_nodes:l["maxNodes"].as_u64().unwrap()as usize,max_depth:l["maxDepth"].as_u64().unwrap()as usize,max_segments:l["maxSegments"].as_u64().unwrap()as usize,max_references:l["maxReferences"].as_u64().unwrap()as usize,max_source_bytes:l["maxSourceBytes"].as_u64().unwrap()as usize};let algorithms=DocumentAlgorithmLimits{max_work:10000000,trace:DocumentTraceLimits{max_pixels:100000,max_admitted_pixels:100000,max_source_bytes:100000,max_edges:65536,max_segments:65536,max_retained_segments:65536,max_work:10000000},booleans:DocumentBooleanLimits{tolerance:0.005,epsilon:1e-8,max_depth:32,max_references:256,max_edges:65536,max_parameters:262144,max_atomic_edges:65536,max_segments:65536,max_retained_segments:262144,max_work:10000000}};let mut producer=DocumentVectorJob::new(&document,limits,algorithms).unwrap();while !producer.advance(4096).unwrap().done{}let(mut retired,output)=producer.into_retirement();while !retired.advance(4096).unwrap().done{}assert!(retired.terminal_is_empty());output.unwrap()
}
fn limits()->PaintedSceneLimits{PaintedSceneLimits{max_nodes:1024,max_segments:65536,max_points:262144,max_contours:65536,max_work:1000000000}}
fn finish(plan:DocumentScenePlan,grant:usize,limits:PaintedSceneLimits)->(PreparedScene,u64){let pointer=plan.nodes.as_ptr();let mut job=ScenePaintJob::new(plan,0.001,limits);assert!(job.result().is_err());let(mut work,mut done)=(0,false);for _ in 0..2000000{let p=job.advance(grant).unwrap();assert!(p.work>work&&p.work-work<=grant as u64);work=p.work;if p.done{done=true;break;}assert!(job.result().is_err());}assert!(done);assert_eq!(job.result().unwrap().plan.nodes.as_ptr(),pointer);let(mut close,output)=job.into_retirement();while !close.advance(grant).unwrap().done{}assert!(close.terminal_is_empty());(output.unwrap(),work)}
fn close(scene:PreparedScene,grant:usize)->u64{let mut close=PreparedSceneCloseJob::new(scene);let mut work=0;while !close.terminal_is_empty(){let p=close.advance(grant).unwrap();assert!(p.work>work&&p.work-work<=grant as u64);work=p.work;}work}
#[test]
fn painted_scene_pairs_owned_plan_and_complete_indexed_cache(){let rows:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let source=row["source"].as_str().unwrap();let(scene,_)=finish(plan(source),grant,limits());assert_eq!(scene.geometry.len(),scene.plan.nodes.len());let actual:Vec<_>=scene.geometry.iter().zip(&scene.plan.nodes).map(|(g,n)|serde_json::json!({"id":n.id,"kind":match &g.paint{PreparedPaint::Empty=>"empty",PreparedPaint::Path(_)=>"path",PreparedPaint::Image(_)=>"image",PreparedPaint::TextFallback(_)=>"textFallback"}})).collect();assert_eq!(actual,row["expected"].as_array().unwrap().clone(),"{source}");assert_eq!(scene.counts.nodes,scene.geometry.len());let points:usize=scene.geometry.iter().map(|g|match &g.paint{PreparedPaint::Empty=>0,PreparedPaint::Path(r)=>r.points,_=>4}).sum();assert_eq!(scene.counts.points,points);let work=close(scene,grant);eprintln!("[DEBUG] Native complete painted scene {source} grant={grant} actual_scene_cache_close_work={work} terminal_empty=true");}}}
#[test]
fn painted_scene_scans_unicode_and_crlf_text_fallback_extent(){let rows:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/📝️text/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let mut source=plan("text stays explicit");let DocumentSceneContent::Text{content,..}=&mut source.nodes[0].content else{panic!("semantic text required")};*content=row["content"].as_str().unwrap().into();let(scene,_)=finish(source,grant,limits());assert!(matches!(scene.geometry[0].paint,PreparedPaint::TextFallback(_)));let width=row["columns"].as_f64().unwrap()*16.0*0.6;let height=row["lines"].as_f64().unwrap()*16.0*1.2;assert_eq!(scene.geometry[0].geometry_bounds,Some([3.0,4.0,3.0+width,4.0+height]));close(scene,grant);}}eprintln!("[DEBUG] Native semantic Unicode and CRLF text fallback remains explicitly tagged and advances under all scene grants");}
#[test]
fn painted_scene_cancels_every_real_private_phase_and_closes_genuine_plan(){let phases:Vec<String>=serde_json::from_str(include_str!("../../🧫️fixtures/🧹️retirement/🔣️.json")).unwrap();for phase in phases{for grant in [1,7,4096]{let mut job=ScenePaintJob::new(plan(if phase=="text"{"text stays explicit"}else{"complete referenced difference"}),0.001,limits());let mut reached=false;for _ in 0..2000000{if job.phase==phase{reached=true;break;}job.advance(1).unwrap();}assert!(reached,"{phase}");let child=job.path.is_some();job.cancel();assert_eq!(job.path.is_some(),child);assert!(job.result().is_err());let(mut close,output)=job.into_retirement();assert!(output.is_none());let mut work=0;while !close.terminal_is_empty(){let p=close.advance(grant).unwrap();assert!(p.work>work&&p.work-work<=grant as u64);work=p.work;}eprintln!("[DEBUG] Native painted scene cancel phase={phase} grant={grant} actual_child_cache_plan_close_work={work} terminal_empty=true");}}}
#[test]
fn painted_scene_owns_refused_input_and_admits_exact_counts_and_work(){let(scene,work)=finish(plan("complete referenced difference"),1,limits());let exact=PaintedSceneLimits{max_nodes:scene.counts.nodes,max_segments:scene.counts.segments,max_points:scene.counts.points,max_contours:scene.counts.contours,max_work:work};close(scene,1);let(scene,_)=finish(plan("complete referenced difference"),7,exact.clone());close(scene,7);for key in 0..5{let mut limits=exact.clone();match key{0=>limits.max_nodes-=1,1=>limits.max_segments-=1,2=>limits.max_points-=1,3=>limits.max_contours-=1,4=>limits.max_work-=1,_=>unreachable!()};let mut job=ScenePaintJob::new(plan("complete referenced difference"),0.001,limits);assert!(job.advance(1000000).is_err());assert!(job.result().is_err());let(mut close,output)=job.into_retirement();assert!(output.is_none());while !close.advance(1).unwrap().done{}assert!(close.terminal_is_empty());}let mut job=ScenePaintJob::new(plan("rectangle"),f64::NAN,limits());for grant in [0,9007199254740992]{assert!(job.advance(grant).is_err());}assert_eq!(job.plan.as_ref().unwrap().nodes.len(),1);assert!(job.advance(1).is_err());let(mut close,output)=job.into_retirement();assert!(output.is_none());while !close.advance(1).unwrap().done{}assert!(close.terminal_is_empty());eprintln!("[DEBUG] Native scene constructor owns refused source; exact count/work admission and one-short limits preserve genuine retirement");}
